"""End-to-end gift order uses no charges, payment records or fabricated fiscal receipts."""
import json,secrets,subprocess
import test_order_lifecycle as orders

class ClosureLifecycle(orders.OrderLifecycle):
 @classmethod
 def setUpClass(cls):
  super().setUpClass();r=subprocess.run([cls.f.php,str(cls.f.path/'scripts/migrate-closure.php'),'up'],capture_output=True,text=True)
  if r.returncode:raise RuntimeError(r.stderr)
 def must(self,r):
  if r.status_code==503:
   import re
   rows=[line.split('NeuroDelo ',1)[1] for line in (self.f.path/'server.log').read_text().splitlines() if 'NeuroDelo {' in line]
   self.fail('HTTP503 safe server metadata: '+str(rows[-3:]))
  return super().must(r)
 def sign(self,b):
  b=self.must(self.action(b,'send'))['record'];r=self.customer.post(self.base+'/customer-api.php?r=collab/upload',data={'project_id':str(self.project_id),'request_key':secrets.token_hex(32)},files={'file':('SYNTHETIC-not-a-real-legal-signature.pdf',self.pdf(),'application/pdf')});b=self.must(self.action(b,'signed-copy',self.customer,file_id=int(self.must(r)['file']['id'])))['record'];return self.must(self.action(b,'verify'))['record']
 def change_signed(self,oid,q,schedule):
  cid=self.must(self.fp(oid,'changes',self.customer,request_body='SYNTHETIC request, previous agreements remain immutable'))['id'];self.must(self.fp(oid,'changes/'+str(cid)+'/propose',version=1,quotation_id=int(q['id']),revised_scope='SYNTHETIC full revised deliverables, no real paid service',schedule_effect='SYNTHETIC revised dates and dependencies',revised_due_on='2099-12-31'));change=next(c for c in self.fg(oid).json()['record']['changes'] if int(c['id'])==cid);self.must(self.fp(oid,'changes/'+str(cid)+'/decide',self.customer,version=int(change['version']),checksum=change['checksum'],decision='ACCEPT'));t=self.approved_template('change_order');b=self.must(self.fp(oid,'generate-change-document',template_id=int(t['id']),change_id=cid,revised_payment_schedule=json.dumps(schedule)))['record'];return cid,self.sign(b)
 def test_close_01_missing_receipts_block_closure_override_preserves_obligations(self):
  oid,items=self.flow_ready();self.must(self.bank(items[0],amount='1.00'));self.assertEqual(self.fp(oid,'close').status_code,409);self.assertEqual(self.fp(oid,'close',override=True).status_code,422)
  r=self.must(self.fp(oid,'close',override=True,acknowledge_remaining_obligations=True,reason='SYNTHETIC isolated case: no real bank transfer or fiscal obligation; test explicit audit override'));self.assertEqual(r['record']['case_state'],'CLOSED');record=self.f.sql('SELECT unresolved_snapshot,override_reason FROM nd_lc_closure_records WHERE order_id=?',params=[oid])[0];self.assertTrue(json.loads(record['unresolved_snapshot']));self.assertIn('SYNTHETIC',record['override_reason']);self.assertEqual(self.lg('finance',self.customer).status_code,200);self.assertEqual(self.f.sql('SELECT state FROM nd_lc_receipt_tasks WHERE order_id=?',params=[oid])[0]['state'],'MISSING');self.assertEqual(self.f.sql("SELECT COUNT(*) n FROM nd_lc_receipt_evidence WHERE action='ISSUANCE_RECORDED'")[0]['n'],0)
 def test_close_02_signed_change_credits_actual_deposit_without_new_income(self):
  oid,items=self.flow_ready();n=int(items[0]['total_minor']);self.must(self.bank(items[0],amount=f'{n//100}.{n%100:02}'));f=self.fg(oid).json()['record'];old_binding=int(f['agreement_binding_id']);old_snapshot=self.lg('documents/'+str(old_binding)).json()['record']['input_snapshot'];q=self.must(self.post(self.owner,f'pricing/projects/{self.project_id}/estimate',packages=self.packages(development_hours='2',testing_hours='2')))['record'];self.must(self.approve(q));q=self.get(self.owner,'pricing/quotes/'+str(q['id'])).json()['record'];total=int(q['calculation']['selling_minor']);schedule=[dict(label='SYNTHETIC revised remaining schedule',amount=f'{total//100}.{total%100:02}',due_on='2099-12-31',gate='handover',stage_id=None)];cid,b=self.change_signed(oid,q,schedule);t=self.approved_template('invoice');version=int(self.fg(oid).json()['record']['version']);k=secrets.token_hex(32);data=dict(version=version,change_id=cid,binding_id=int(b['id']),invoice_template_id=int(t['id']),request_key=k);r=self.must(self.fp(oid,'apply-change',**data));replay=self.must(self.fp(oid,'apply-change',**data));self.assertEqual(replay['id'],r['id']);self.assertTrue(replay['action_replayed']);stored=self.f.sql('SELECT result FROM nd_crm_requests WHERE request_key=?',params=[k])[0]['result'];self.assertLess(len(stored.encode()),2000);self.assertNotIn('record',json.loads(stored));f=r['record'];self.assertEqual(f['payment']['net_minor'],n);self.assertEqual(f['payment']['outstanding_minor'],total-n);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_payment_transactions t JOIN nd_payment_attempts p ON p.id=t.attempt_id JOIN nd_invoices i ON i.id=p.invoice_id WHERE i.order_id=?',params=[oid])[0]['n'],1);self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM nd_lc_receipt_tasks WHERE order_id=?',params=[oid])[0]['n'],1);self.assertEqual(self.lg('documents/'+str(old_binding)).json()['record']['input_snapshot'],old_snapshot);self.assertEqual(int(self.f.sql('SELECT credited_actual_income_minor FROM nd_lc_change_applications WHERE change_id=?',params=[cid])[0]['credited_actual_income_minor']),n)

for name in dir(orders.OrderLifecycle):
 if name.startswith('test_'):setattr(ClosureLifecycle,name,None)

class ZeroChargeEndToEnd(ClosureLifecycle):
 def approved_price(self):
  super().approved_price();q=self.must(self.post(self.owner,f'pricing/projects/{self.project_id}/estimate',packages=self.packages(development_hours='0',testing_hours='0')))['record'];self.must(self.approve(q));return self.get(self.owner,'pricing/quotes/'+str(q['id'])).json()['record']
 def inputs(self):
  d=super().inputs();d['payment_schedule']='[]';return d
 def test_zero_complete_lifecycle_without_charge_or_fake_receipt(self):
  oid,items=self.flow_ready();self.assertEqual(items,[]);f=self.fg(oid).json()['record'];self.assertEqual(f['payment']['state'],'SETTLED');self.assertTrue(f['payment']['no_payment_obligation']);self.material_ready(oid);self.must(self.fp(oid,'start-production'));stage=self.stage();vid=self.must(self.fp(oid,'milestones',**self.evidence(stage)))['id'];self.must(self.respond(oid,vid,'ACCEPT'));self.must(self.fp(oid,'request-final'));f=self.fg(oid).json()['record'];self.must(self.fp(oid,'decision/FINAL',self.customer,checksum=f['final_hash'],decision='ACCEPT'));f=self.fg(oid).json()['record'];agreement=self.lg('documents/'+str(f['agreement_binding_id'])).json()['record'];terms=json.loads(agreement['input_snapshot'])['fields']['support_terms'];self.must(self.fp(oid,'support',support_terms=terms,support_start=None,support_end=None));t=self.approved_template('acceptance');act=self.must(self.fp(oid,'generate-act',template_id=int(t['id'])))['record'];source=json.loads(act['input_snapshot'])['lifecycle_source'];self.assertEqual(source['final_manifest_hash'],f['final_hash']);self.assertEqual(source['milestones'][0]['version_id'],vid);act=self.sign(act);self.must(self.fp(oid,'bind-act',binding_id=int(act['id'])))
  r=self.owner.post(self.base+'/api.php?r=crm/collab/upload',data={'project_id':str(self.project_id),'request_key':secrets.token_hex(32),'visibility':'internal'},files={'file':('SYNTHETIC-handover-instructions.pdf',self.pdf(),'application/pdf')});fid=int(self.must(r)['file']['id']);self.material_ready(oid,'HANDOVER',fid);self.must(self.fp(oid,'prepare-handover'));t=self.approved_template('handover');doc=self.must(self.fp(oid,'generate-handover',template_id=int(t['id'])))['record'];doc=self.must(self.action(doc,'send'))['record'];self.must(self.fp(oid,'bind-handover',binding_id=int(doc['id'])));f=self.fg(oid,self.customer).json()['record'];self.must(self.fp(oid,'decision/HANDOVER',self.customer,checksum=f['handover_hash'],decision='ACCEPT'));f=self.fg(oid).json()['record'];self.assertEqual(f['closure_obligations'],[]);closed=self.must(self.fp(oid,'close'))['record'];self.assertEqual(closed['case_state'],'CLOSED');self.assertIsNone(closed['closure_record']['override_reason']);self.assertEqual(self.fg(oid,self.customer).status_code,200)
  for table in ['nd_payment_transactions','nd_payment_attempts','nd_lc_receipt_tasks','nd_lc_receipt_evidence']:self.assertEqual(self.f.sql('SELECT COUNT(*) n FROM '+table)[0]['n'],0,table)

for name in dir(ClosureLifecycle):
 if name.startswith('test_'):setattr(ZeroChargeEndToEnd,name,None)
